mapper.select:
/*BoardMapper.selectBoardCnt */
	SELECT 
		COUNT(board_idx)
	FROM BOARD
	WHERE BOARD_ID = #{boardId}
	
		
		
		AND BOARD_TITLE LIKE CONCAT('%', #{keyWord}, '%')
		
		
		AND BOARD_CONTENT LIKE CONCAT('%', #{keyWord}, '%')
		
		
		AND BOARD_WRITER = #{keyWord}
		AND BOARD_WRITER LIKE CONCAT('%', #{keyWord}, '%')

/*BoardMapper.selectBoardList */ SELECT BOARD_IDX, BOARD_ID, BOARD_TITLE , BOARD_CNT , DATE_FORMAT(REG_DATE,'%Y-%m-%d') AS REG_DATE , M.M_NAME AS BOARD_WRITER FROM BOARD B LEFT JOIN MEMBER M ON M.M_ID = B.BOARD_WRITER WHERE BOARD_ID = #{boardId}
AND BOARD_TITLE LIKE CONCAT('%', #{keyWord}, '%')
AND BOARD_CONTENT LIKE CONCAT('%', #{keyWord}, '%')
AND BOARD_WRITER = #{keyWord} AND BOARD_WRITER LIKE CONCAT('%', #{keyWord}, '%')
ORDER BY REG_DATE, BOARD_IDX DESC LIMIT #{offset} , #{recordSize}

/*BoardMapper.selectBoardView */
	SELECT 
		BOARD_IDX, BOARD_ID, BOARD_TITLE
		, BOARD_CNT
		, DATE_FORMAT(REG_DATE,'%Y-%m-%d') AS REG_DATE
		, M.M_NAME AS BOARD_WRITER
	FROM BOARD B
	LEFT JOIN MEMBER M ON M.M_ID = B.BOARD_WRITER 
	WHERE BOARD_ID = #{boardId}
	AND BOARD_IDX = #{boardIdx}
